16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    public void setTelephone(String telephone) {
89	        this.telephone = normalizeTelephone(telephone);
90	    }
91	
92	    /**
93	     * Normalises a telephone number to digits only by stripping spaces, dashes
94	     * and parentheses, so that formatted inputs such as {@code "(613) 555-0100"}
95	     * and {@code "6135550100"} are stored and compared identically.
96	     *
97	     * @param telephone the raw telephone value (may be {@code null})
98	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
99	     */
100	    private static String normalizeTelephone(String telephone) {
101	        if (telephone == null) {
102	            return null;
103	        }
104	        return telephone.replaceAll("[\\s()-]", "");
105	    }
106	
107	    public String getEmail() {
108	        return this.email;
109	    }
110	
111	    public void setEmail(String email) {
112	        this.email = email;
113	    }
114	
115	    public LocalDate getRegistrationDate() {
116	        return this.registrationDate;
117	    }
118	
119	    public void setRegistrationDate(LocalDate registrationDate) {
120	        this.registrationDate = registrationDate;
121	    }
122	
123	    public Integer getMembershipNumber() {
124	        return this.membershipNumber;
125	    }
126	
127	    public void setMembershipNumber(Integer membershipNumber) {
128	        this.membershipNumber = membershipNumber;
129	    }
130	
131	    public String getCustomerCode() {
132	        return this.customerCode;
133	    }
134	
135	    public void setCustomerCode(String customerCode) {
136	        this.customerCode = customerCode;
137	    }
138	
139	    protected Set<Pet> getPetsInternal() {
140	        if (this.pets == null) {
141	            this.pets = new HashSet<>();
142	        }
143	        return this.pets;
144	    }
145	
146	    protected void setPetsInternal(Set<Pet> pets) {
147	        this.pets = pets;
148	    }
149	
150	    public List<Pet> getPets() {
151	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
152	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
153	        return Collections.unmodifiableList(sortedPets);
154	    }
155	
156	    public void setPets(List<Pet> pets) {
157	        this.pets = new HashSet<>(pets);
158	    }
159	
160	    public void addPet(Pet pet) {
161	        getPetsInternal().add(pet);
162	        pet.setOwner(this);
163	    }
164	
165	    /**
166	     * Return the Pet with the given name, or null if none found for this Owner.
167	     *
168	     * @param name to test
169	     * @return true if pet name is already in use
170	     */
171	    public Pet getPet(String name) {
172	        return getPet(name, false);
173	    }
174	
175	    /**
176	     * Return the Pet with the given name, or null if none found for this Owner.
177	     *
178	     * @param name to test
179	     * @return true if pet name is already in use
180	     */
181	    public Pet getPet(String name, boolean ignoreNew) {
182	        name = name.toLowerCase();
183	        for (Pet pet : getPetsInternal()) {
184	            if (!ignoreNew || !pet.isNew()) {
185	                String compName = pet.getName();
186	                compName = compName.toLowerCase();
187	                if (compName.equals(name)) {
188	                    return pet;
189	                }
190	            }
191	        }
192	        return null;
193	    }
194	
195	    public Pet getPet(Integer petId) {
196	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
197	    }
198	
199	    @Override
200	    public String toString() {
201	        return new ToStringCreator(this)
202	
203	            .append("id", this.getId())
204	            .append("new", this.isNew())
205	            .append("lastName", this.getLastName())
206	            .append("firstName", this.getFirstName())
207	            .append("address", this.address)
208	            .append("city", this.city)
209	            .append("telephone", this.telephone)
210	            .toString();
211	    }
212	}
