17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (owner.getRegistrationDate() == null) {
107	            owner.setRegistrationDate(LocalDate.now());
108	        }
109	        if (this.clinicService.existsIdenticalOwner(owner)
110	            || this.clinicService.existsOwnerWithTelephone(owner.getTelephone())
111	            || this.clinicService.existsOwnerWithEmail(owner.getEmail())) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
115	        owner.setCity(resolveCityName(owner.getCity()));
116	        long ownersInCity = this.clinicService.findAllOwners().stream()
117	            .filter(existing -> existing.getCity() != null
118	                && existing.getCity().equalsIgnoreCase(owner.getCity()))
119	            .count();
120	        owner.setCustomerCode(String.format("%s-%04d",
121	            owner.getCity().toUpperCase(Locale.ROOT), ownersInCity + 1));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * Resolves the city name to store for a newly created owner. If another owner already
131	     * lives in the same city (compared case-insensitively), that owner's exact spelling of
132	     * the city is reused so a city keeps a single canonical spelling. Otherwise the supplied
133	     * city is title-cased (each word capitalised, remaining letters lower-cased).
134	     *
135	     * @param city the raw city supplied for the new owner (may be {@code null})
136	     * @return the city name to store, or {@code null} if {@code city} is {@code null}
137	     */
138	    private String resolveCityName(String city) {
139	        if (city == null) {
140	            return null;
141	        }
142	        return this.clinicService.findAllOwners().stream()
143	            .map(Owner::getCity)
144	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
145	            .findFirst()
146	            .orElseGet(() -> toTitleCase(city));
147	    }
148	
149	    /**
150	     * Title-cases a city name: the first letter of every whitespace-separated word is
151	     * upper-cased and the remaining letters are lower-cased, e.g. {@code "new  YORK"}
152	     * becomes {@code "New  York"}. Whitespace is preserved as-is.
153	     *
154	     * @param city the city name to title-case
155	     * @return the title-cased city name
156	     */
157	    private static String toTitleCase(String city) {
158	        StringBuilder result = new StringBuilder(city.length());
159	        boolean startOfWord = true;
160	        for (int i = 0; i < city.length(); i++) {
161	            char c = city.charAt(i);
162	            if (Character.isWhitespace(c)) {
163	                startOfWord = true;
164	                result.append(c);
165	            } else {
166	                result.append(startOfWord
167	                    ? Character.toTitleCase(c)
168	                    : Character.toLowerCase(c));
169	                startOfWord = false;
170	            }
171	        }
172	        return result.toString();
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
178	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
179	        if (currentOwner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        currentOwner.setAddress(ownerFieldsDto.getAddress());
183	        currentOwner.setCity(ownerFieldsDto.getCity());
184	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
185	        currentOwner.setLastName(ownerFieldsDto.getLastName());
186	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
187	        this.clinicService.saveOwner(currentOwner);
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Transactional
193	    @Override
194	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        this.clinicService.deleteOwner(owner);
200	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Pet pet = petMapper.toPet(petFieldsDto);
212	        owner.setId(ownerId);
213	        pet.setOwner(owner);
214	        pet.getType().setName(null);
215	        this.clinicService.savePet(pet);
216	        PetDto petDto = petMapper.toPetDto(pet);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
218	            .buildAndExpand(pet.getId()).toUri());
219	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
225	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
226	        if (currentOwner != null) {
227	            Pet currentPet = this.clinicService.findPetById(petId);
228	            if (currentPet != null) {
229	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
230	                currentPet.setName(petFieldsDto.getName());
231	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
232	                this.clinicService.savePet(currentPet);
233	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
242	        HttpHeaders headers = new HttpHeaders();
243	        Visit visit = visitMapper.toVisit(visitFieldsDto);
244	        Pet pet = new Pet();
245	        pet.setId(petId);
246	        visit.setPet(pet);
247	        this.clinicService.saveVisit(visit);
248	        VisitDto visitDto = visitMapper.toVisitDto(visit);
249	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
250	            .buildAndExpand(visit.getId()).toUri());
251	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
252	    }
253	
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner != null) {
260	            Pet pet = owner.getPet(petId);
261	            if (pet != null) {
262	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	}
